SELECT id,task_id,product_id,task_name,product_name, create_time,update_time,message_content,notice_node, notice_message_id,notice_user_id,plan_end_time,is_task, charge_id,charge_name FROM notice_message_record WHERE notice_user_id=#{params.flagId}
AND product_name LIKE concat('%',#{params.searchKeyword},'%'))
ORDER BY create_time DESC
